"""Embed every workbook in data/ into app/workbooks.js so the app works offline.

Run after replacing or adding an .xlsx in data/:
    python3 tools/build_workbooks.py
"""
import base64
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
files = sorted((ROOT / "data").glob("*.xlsx"))
entries = [
    {"file": f.name, "data": base64.b64encode(f.read_bytes()).decode("ascii")}
    for f in files
]
out = ROOT / "app" / "workbooks.js"
out.write_text(
    "// Generated by tools/build_workbooks.py from data/*.xlsx. Do not edit by hand.\n"
    "window.MIS_WORKBOOKS = " + json.dumps(entries) + ";\n",
    encoding="utf-8",
)
print(f"Embedded {len(entries)} workbook(s) into {out.relative_to(ROOT)} ({out.stat().st_size // 1024} KB)")
